/* G3 Sec 4 generators: Ch1 Set Language and Notation, Ch2 Data Analysis (cumulative frequency, quartiles, box plots,
   standard deviation), Ch3 Probability of Combined Events, Ch4 Matrices, Ch5 Vectors in Two Dimensions (2 gyms). */
'use strict';
module.exports = function(H){
  const {blank, gcd, sp} = H, B = blank;
  const rd = (x, d) => +x.toFixed(d), g = [];
  const sum = a => a.reduce((x, y) => x + y, 0);
  const sorted = a => [...a].sort((x, y) => x - y);
  const median = a => { const s = sorted(a), n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; };
  const quart = a => { const s = sorted(a), n = s.length, lo = s.slice(0, Math.floor(n / 2)), hi = s.slice(Math.ceil(n / 2)); return {q1: median(lo), q2: median(s), q3: median(hi)}; };
  const dl = (r, n, lo, hi) => Array.from({length: n}, () => r.int(lo, hi));
  const sd = a => { const m = sum(a) / a.length; return Math.sqrt(sum(a.map(x => (x - m) ** 2)) / a.length); };

  /* ---- Set language and notation ---- */
  g.push({id: 'G3.4.set-language-and-notation.1', plain: [
    r => { const a = r.int(10, 30), b = r.int(8, 25), c = r.int(2, 7); return B(`$n(A) = ${a}$, $n(B) = ${b}$ and $n(A \\cap B) = ${c}$. Find $n(A \\cup B)$.`, a + b - c, `$n(A \\cup B) = ${a} + ${b} - ${c} = ${a + b - c}$.`); },
    r => { const a = r.int(10, 30), b = r.int(8, 25), c = r.int(2, 7); return B(`$n(A) = ${a}$, $n(B) = ${b}$ and $n(A \\cup B) = ${a + b - c}$. Find $n(A \\cap B)$.`, c, `$n(A \\cap B) = ${a} + ${b} - ${a + b - c} = ${c}$.`); },
    r => { const a = r.int(10, 30), c = r.int(2, 9); return B(`$n(A) = ${a}$ and $n(A \\cap B) = ${c}$. Find the number of elements in $A$ only (in $A$ but not in $B$).`, a - c, `${a} − ${c} = ${a - c}.`); },
    r => { const e = r.int(30, 60), a = r.int(10, 25); return B(`$n(\\xi) = ${e}$ and $n(A) = ${a}$. Find $n(A')$.`, e - a, `$n(A') = ${e} - ${a} = ${e - a}$.`); },
    r => { const e = r.int(40, 70), u = r.int(20, 35); return B(`$n(\\xi) = ${e}$ and $n(A \\cup B) = ${u}$. Find $n((A \\cup B)')$.`, e - u, `${e} − ${u} = ${e - u}.`); },
    r => { const n = r.int(3, 7); return B(`A set has ${n} elements. How many subsets does it have (including the empty set and the set itself)?`, 2 ** n, `$2^{${n}} = ${2 ** n}$.`); },
    r => { const n = r.int(3, 6); return B(`A set has ${n} elements. How many proper subsets does it have?`, 2 ** n - 1, `$2^{${n}} - 1 = ${2 ** n - 1}$.`); },
    r => { const k = r.int(3, 9), N = k * r.int(5, 12); return B(`$A$ is the set of multiples of ${k} from 1 to ${N}. Find $n(A)$.`, N / k, `${N} ÷ ${k} = ${N / k}.`); },
    r => { const N = r.pick([30, 60, 90, 120]); return B(`$\\xi = \\{1, 2, 3, \\ldots, ${N}\\}$. $A$ is the set of even numbers and $B$ is the set of multiples of 3. Find $n(A \\cap B)$.`, N / 6, `$A \\cap B$ is the set of multiples of 6: ${N} ÷ 6 = ${N / 6}.`); },
    r => { const a = r.int(1, 8), b = r.int(a + 5, a + 20); return B(`$A = \\{x : x \\text{ is an integer}, ${a} < x \\le ${b}\\}$. Find $n(A)$.`, b - a, `The integers are ${a + 1}, …, ${b}: ${b - a} of them.`); },
    r => { const N = r.pick([20, 30, 40, 50]); const primes = []; for (let i = 2; i < N; i++) { let p = true; for (let j = 2; j * j <= i; j++) if (i % j === 0) p = false; if (p) primes.push(i); } return B(`$P$ is the set of prime numbers less than ${N}. Find $n(P)$.`, primes.length, `The primes are ${primes.join(', ')}: ${primes.length} of them.`); },
    r => { const b = r.int(10, 25), c = r.int(2, 8); return B(`$n(B) = ${b}$ and $n(A \\cap B) = ${c}$. Find $n(A' \\cap B)$.`, b - c, `$n(A' \\cap B) = n(B) - n(A \\cap B) = ${b} - ${c} = ${b - c}$.`); },
    r => { const a = r.int(5, 15), b = r.int(a + 3, a + 12); return B(`$A \\subset B$, $n(A) = ${a}$ and $n(B) = ${b}$. Find $n(A \\cup B)$.`, b, 'If $A$ is a subset of $B$ then $A \\cup B = B$.'); },
    r => { const a = r.int(5, 15), b = r.int(a + 3, a + 12); return B(`$A \\subset B$, $n(A) = ${a}$ and $n(B) = ${b}$. Find $n(A \\cap B)$.`, a, 'If $A$ is a subset of $B$ then $A \\cap B = A$.'); },
    r => { const a = r.int(5, 15), b = r.int(5, 15); return B(`$A$ and $B$ are disjoint sets with $n(A) = ${a}$ and $n(B) = ${b}$. Find $n(A \\cup B)$.`, a + b, `Disjoint sets have $n(A \\cap B) = 0$, so $n(A \\cup B) = ${a + b}$.`); }
  ], word: [
    r => { const N = r.int(35, 50), f = r.int(18, 28), b = r.int(15, 25), none = r.int(2, 6); const both = f + b - (N - none); if (both < 1) return null; return B(`In a class of ${N} students, ${f} play football, ${b} play basketball and ${none} play neither. How many play both games?`, both, `Players of at least one game = ${N} − ${none} = ${N - none}. Both = ${f} + ${b} − ${N - none} = ${both}.`); },
    r => { const N = r.int(40, 60), a = r.int(20, 30), b = r.int(18, 28), both = r.int(5, 12), none = N - (a + b - both); if (none < 0) return null; return B(`Of ${N} pupils, ${a} like Maths, ${b} like Science and ${both} like both. How many like neither subject?`, none, `At least one = ${a} + ${b} − ${both} = ${a + b - both}. Neither = ${N} − ${a + b - both} = ${none}.`); },
    r => { const a = r.int(15, 30), both = r.int(4, 10); return B(`In a survey, ${a} people speak Malay and ${both} of them also speak Tamil. How many speak Malay but not Tamil?`, a - both, `${a} − ${both} = ${a - both}.`); },
    r => { const N = r.int(30, 45), c = r.int(14, 22), d = r.int(10, 18), both = r.int(3, 8); return B(`In a group of ${N} children, ${c} own cats, ${d} own dogs and ${both} own both. How many own at least one of the two pets?`, c + d - both, `${c} + ${d} − ${both} = ${c + d - both}.`); },
r => { const N = r.int(50, 80), a = r.int(25, 40); return B(`There are ${N} members in a club and ${a} of them play chess. How many members do not play chess?`, N - a, `${N} − ${a} = ${N - a}.`); },
    r => { const a = r.int(10, 20), b = r.int(10, 20), both = r.int(2, 8); return B(`${a} students joined the Art Club and ${b} joined the Music Club. ${both} joined both. How many students joined at least one club?`, a + b - both, `${a} + ${b} − ${both} = ${a + b - both}.`); }
  ]});

  /* ---- Data analysis: cumulative frequency diagrams ---- */
  const classes = ['0 < x ≤ 10', '10 < x ≤ 20', '20 < x ≤ 30', '30 < x ≤ 40', '40 < x ≤ 50'];
  const cfq = (r) => { const f = [r.int(2, 8), r.int(4, 12), r.int(6, 16), r.int(4, 12), r.int(2, 8)]; const cf = f.map((v, i) => sum(f.slice(0, i + 1))); return {f, cf, n: cf[4]}; };
  g.push({id: 'G3.4.data-analysis-measures-of-spread.1', plain: [
    r => { const {f, cf} = cfq(r); return B(`A grouped frequency table has classes ${classes.join(', ')} with frequencies ${f.join(', ')}. Find the cumulative frequency for $x \\le 30$.`, cf[2], `${f.slice(0, 3).join(' + ')} = ${cf[2]}.`); },
    r => { const {f, cf, n} = cfq(r); return B(`A grouped frequency table has classes ${classes.join(', ')} with frequencies ${f.join(', ')}. How many values are greater than 30?`, n - cf[2], `Total = ${n}. Cumulative frequency at 30 = ${cf[2]}. So ${n} − ${cf[2]} = ${n - cf[2]}.`); },
    r => { const {f, cf, n} = cfq(r); return B(`A grouped frequency table has classes ${classes.join(', ')} with frequencies ${f.join(', ')}. Find the total frequency.`, n, `${f.join(' + ')} = ${n}.`); },
    r => { const {f, cf, n} = cfq(r); return B(`The cumulative frequencies at 10, 20, 30, 40 and 50 are ${cf.join(', ')}. Find the frequency of the class $30 < x \\le 40$.`, f[3], `${cf[3]} − ${cf[2]} = ${f[3]}.`); },
    r => { const {f, cf, n} = cfq(r); const n4 = n; return B(`A cumulative frequency curve is drawn for ${n} values. At which position (counting from the smallest) is the median read from the curve? Give the position as a decimal.`, n / 2, `The median is at the $\\dfrac{n}{2}$th value: ${n} ÷ 2 = ${n / 2}.`); },
    r => { const n = r.pick([40, 60, 80, 100, 120, 200]); return B(`A cumulative frequency curve is drawn for ${n} values. At which position is the lower quartile read from the curve?`, n / 4, `$Q_1$ is at $\\dfrac{n}{4} = ${n / 4}$.`); },
    r => { const n = r.pick([40, 60, 80, 100, 120, 200]); return B(`A cumulative frequency curve is drawn for ${n} values. At which position is the upper quartile read from the curve?`, 3 * n / 4, `$Q_3$ is at $\\dfrac{3n}{4} = ${3 * n / 4}$.`); },
    r => { const n = r.pick([50, 80, 100, 150, 200, 250]), p = r.pick([10, 20, 40, 60, 80, 90]); return B(`A cumulative frequency curve is drawn for ${n} values. At which position is the ${p}th percentile read?`, n * p / 100, `${p}% of ${n} = ${n * p / 100}.`); },
    r => { const {f, cf, n} = cfq(r); return B(`The cumulative frequencies at 10, 20, 30, 40 and 50 are ${cf.join(', ')}. How many values are between 20 and 40?`, cf[3] - cf[1], `${cf[3]} − ${cf[1]} = ${cf[3] - cf[1]}.`); },
    r => { const {f, cf, n} = cfq(r); return B(`The cumulative frequencies at 10, 20, 30, 40 and 50 are ${cf.join(', ')}. What percentage of the values are at most 20? Give your answer correct to 1 decimal place.`, rd(cf[1] / n * 100, 1), `${cf[1]}/${n} × 100 = ${rd(cf[1] / n * 100, 1)}%.`); },
    r => { const {f, cf, n} = cfq(r); return B(`The cumulative frequencies at 10, 20, 30, 40 and 50 are ${cf.join(', ')}. What percentage of the values are more than 30? Give your answer correct to 1 decimal place.`, rd((n - cf[2]) / n * 100, 1), `(${n} − ${cf[2]})/${n} × 100 = ${rd((n - cf[2]) / n * 100, 1)}%.`); },
    r => { const {f, cf, n} = cfq(r); const half = n / 2; let cls = cf.findIndex(c => c >= half); return B(`A grouped frequency table has classes ${classes.join(', ')} with frequencies ${f.join(', ')}. Find the upper limit of the class that contains the median.`, (cls + 1) * 10, `Total = ${n}. The median is at position ${n / 2}. The cumulative frequencies are ${cf.join(', ')}, so it lies in the class ending at ${(cls + 1) * 10}.`); },
    r => { const {f, cf, n} = cfq(r); return B(`Marks are grouped as ${classes.join(', ')} with frequencies ${f.join(', ')}. How many values are at most 10?`, cf[0], `The first class has frequency ${cf[0]}.`); },
    r => { const n = r.pick([40, 60, 80, 100, 120, 200]); return B(`For ${n} values, find the position used to read the interquartile range's two quartiles: give the difference between the positions of $Q_3$ and $Q_1$.`, n / 2, `$3n/4 - n/4 = n/2 = ${n / 2}$.`); },
r => { const {f, cf, n} = cfq(r); return B(`The cumulative frequencies at 10, 20, 30, 40 and 50 are ${cf.join(', ')}. How many values are greater than 40?`, n - cf[3], `${n} − ${cf[3]} = ${n - cf[3]}.`); }
  ], word: [
    r => { const {f, cf, n} = cfq(r); return B(`The times (in minutes) taken by ${n} students to finish a test are grouped in 10-minute classes up to 50 with frequencies ${f.join(', ')}. How many students took more than 30 minutes?`, n - cf[2], `${n} − ${cf[2]} = ${n - cf[2]}.`); },
    r => { const n = r.pick([80, 100, 120, 160, 200]), p = r.pick([10, 20, 40, 60, 90]); return B(`${n} students sat an exam. The marks are shown on a cumulative frequency curve. Students with marks above the ${p}th percentile receive a prize. How many students are at or below the ${p}th percentile?`, n * p / 100, `${p}% of ${n} = ${n * p / 100}.`); },
    r => { const {f, cf, n} = cfq(r); return B(`A cumulative frequency table of waiting times (minutes) at a clinic shows ${cf.join(', ')} patients waited at most 10, 20, 30, 40 and 50 minutes respectively. How many patients waited between 20 and 40 minutes?`, cf[3] - cf[1], `${cf[3]} − ${cf[1]} = ${cf[3] - cf[1]}.`); },
    r => { const {f, cf, n} = cfq(r); return B(`A cumulative frequency table of the heights of ${n} plants shows ${cf.join(', ')} plants at most 10, 20, 30, 40 and 50 cm tall. What percentage of plants are taller than 30 cm, correct to 1 decimal place?`, rd((n - cf[2]) / n * 100, 1), `(${n} − ${cf[2]})/${n} × 100 = ${rd((n - cf[2]) / n * 100, 1)}%.`); },
    r => { const n = r.pick([60, 100, 120, 200]); return B(`A delivery company records ${n} delivery times. Half the deliveries took less than the median time. How many deliveries took less than the median time?`, n / 2, `${n} ÷ 2 = ${n / 2}.`); },
    r => { const n = r.pick([40, 80, 100, 200]), q = r.pick([25, 75]); return B(`The exam marks of ${n} students are shown on a cumulative frequency graph. How many students scored at or below the ${q === 25 ? 'lower' : 'upper'} quartile mark?`, n * q / 100, `${q}% of ${n} = ${n * q / 100}.`); }
  ]});

  /* ---- Range, quartiles and percentiles ---- */
  g.push({id: 'G3.4.data-analysis-measures-of-spread.2', plain: [
    r => { const d = dl(r, 7, 3, 60); return B(`Find the lower quartile $Q_1$ of ${d.join(', ')}.`, quart(d).q1, `In order: ${sorted(d).join(', ')}. $Q_1$ is the median of the lower half: ${quart(d).q1}.`); },
    r => { const d = dl(r, 7, 3, 60); return B(`Find the upper quartile $Q_3$ of ${d.join(', ')}.`, quart(d).q3, `In order: ${sorted(d).join(', ')}. $Q_3$ is the median of the upper half: ${quart(d).q3}.`); },
    r => { const d = dl(r, 8, 3, 60); return B(`Find the interquartile range of ${d.join(', ')}.`, quart(d).q3 - quart(d).q1, `In order: ${sorted(d).join(', ')}. $Q_1 = ${quart(d).q1}$, $Q_3 = ${quart(d).q3}$. IQR = ${quart(d).q3 - quart(d).q1}.`); },
    r => { const d = dl(r, 9, 5, 80); return B(`Find the range of ${d.join(', ')}.`, Math.max(...d) - Math.min(...d), `${Math.max(...d)} − ${Math.min(...d)} = ${Math.max(...d) - Math.min(...d)}.`); },
    r => { const d = dl(r, 11, 3, 50); return B(`Find the median of ${d.join(', ')}.`, median(d), `In order: ${sorted(d).join(', ')}. The median is ${median(d)}.`); },
    r => { const q1 = r.int(10, 30), iqr = r.int(8, 20); return B(`The lower quartile of a data set is ${q1} and the interquartile range is ${iqr}. Find the upper quartile.`, q1 + iqr, `$Q_3 = ${q1} + ${iqr} = ${q1 + iqr}$.`); },
    r => { const q3 = r.int(40, 70), iqr = r.int(8, 20); return B(`The upper quartile of a data set is ${q3} and the interquartile range is ${iqr}. Find the lower quartile.`, q3 - iqr, `$Q_1 = ${q3} - ${iqr} = ${q3 - iqr}$.`); },
    r => { const n = r.pick([20, 40, 60, 80, 100]), p = r.pick([10, 25, 50, 75, 90]); return B(`In a data set of ${n} values, how many values lie below the ${p}th percentile?`, n * p / 100, `${p}% of ${n} = ${n * p / 100}.`); },
    r => { const d = dl(r, 10, 3, 60); return B(`Find the lower quartile of ${d.join(', ')}.`, quart(d).q1, `In order: ${sorted(d).join(', ')}. The lower half is ${sorted(d).slice(0, 5).join(', ')}, with median ${quart(d).q1}.`); },
    r => { const d = dl(r, 10, 3, 60); return B(`Find the upper quartile of ${d.join(', ')}.`, quart(d).q3, `In order: ${sorted(d).join(', ')}. The upper half is ${sorted(d).slice(5).join(', ')}, with median ${quart(d).q3}.`); },
    r => { const lo = r.int(5, 15), q1 = lo + r.int(5, 12), m = q1 + r.int(4, 10), q3 = m + r.int(4, 10), hi = q3 + r.int(6, 15); return B(`A data set has minimum ${lo}, $Q_1 = ${q1}$, median ${m}, $Q_3 = ${q3}$ and maximum ${hi}. Find the range.`, hi - lo, `${hi} − ${lo} = ${hi - lo}.`); },
    r => { const lo = r.int(5, 15), q1 = lo + r.int(5, 12), m = q1 + r.int(4, 10), q3 = m + r.int(4, 10), hi = q3 + r.int(6, 15); return B(`A data set has minimum ${lo}, $Q_1 = ${q1}$, median ${m}, $Q_3 = ${q3}$ and maximum ${hi}. Find the interquartile range.`, q3 - q1, `${q3} − ${q1} = ${q3 - q1}.`); },
    r => { const n = r.pick([40, 60, 80, 120]); return B(`The interquartile range of ${n} values covers the middle half of the data. How many values lie between $Q_1$ and $Q_3$?`, n / 2, `Half of ${n} = ${n / 2}.`); },
    r => { const d = dl(r, 6, 3, 40); return B(`Find the median of ${d.join(', ')}.`, median(d), `In order: ${sorted(d).join(', ')}. The median is ${median(d)}.`); },
    r => { const q1 = r.int(12, 30), q3 = q1 + r.int(8, 20); return B(`A data set has $Q_1 = ${q1}$ and $Q_3 = ${q3}$. Find the value of $Q_3 + 1.5 \\times IQR$.`, q3 + 1.5 * (q3 - q1), `IQR = ${q3 - q1}. $${q3} + 1.5 \\times ${q3 - q1} = ${q3 + 1.5 * (q3 - q1)}$.`); }
  ], word: [
    r => { const d = dl(r, 9, 40, 99); return B(`The marks of 9 students are ${d.join(', ')}. Find the interquartile range of the marks.`, quart(d).q3 - quart(d).q1, `In order: ${sorted(d).join(', ')}. $Q_1 = ${quart(d).q1}$, $Q_3 = ${quart(d).q3}$. IQR = ${quart(d).q3 - quart(d).q1}.`); },
    r => { const d = dl(r, 8, 20, 70); return B(`The ages of 8 members of a club are ${d.join(', ')}. Find the range of their ages.`, Math.max(...d) - Math.min(...d), `${Math.max(...d)} − ${Math.min(...d)} = ${Math.max(...d) - Math.min(...d)}.`); },
    r => { const n = r.pick([60, 80, 100, 200]), p = r.pick([25, 50, 75]); return B(`A school has ${n} students in a year group. A student at the ${p}th percentile of the exam marks has the same mark as or higher than ${p}% of the group. How many students scored below the ${p}th percentile mark?`, n * p / 100, `${p}% of ${n} = ${n * p / 100}.`); },
    r => { const d = dl(r, 7, 15, 60); return B(`The daily sales (in dollars) of a stall over 7 days are ${d.join(', ')}. Find the median daily sales.`, median(d), `In order: ${sorted(d).join(', ')}. The median is ${median(d)}.`); },
    r => { const d = dl(r, 10, 20, 90); return B(`The waiting times (in minutes) of 10 patients are ${d.join(', ')}. Find the upper quartile.`, quart(d).q3, `In order: ${sorted(d).join(', ')}. The upper half has median ${quart(d).q3}.`); },
    r => { const q1 = r.int(35, 55), q3 = q1 + r.int(10, 25); return B(`The test marks in a class have $Q_1 = ${q1}$ and $Q_3 = ${q3}$. What is the interquartile range?`, q3 - q1, `${q3} − ${q1} = ${q3 - q1}.`); }
  ]});

  /* ---- Box-and-whisker plots ---- */
  const five = r => { const lo = r.int(5, 20), q1 = lo + r.int(4, 12), m = q1 + r.int(3, 10), q3 = m + r.int(3, 10), hi = q3 + r.int(5, 15); return {lo, q1, m, q3, hi}; };
  g.push({id: 'G3.4.data-analysis-measures-of-spread.3', plain: [
    r => { const f = five(r); return B(`A box-and-whisker plot has minimum ${f.lo}, $Q_1 = ${f.q1}$, median ${f.m}, $Q_3 = ${f.q3}$ and maximum ${f.hi}. Find the range.`, f.hi - f.lo, `${f.hi} − ${f.lo} = ${f.hi - f.lo}.`); },
    r => { const f = five(r); return B(`A box-and-whisker plot has minimum ${f.lo}, $Q_1 = ${f.q1}$, median ${f.m}, $Q_3 = ${f.q3}$ and maximum ${f.hi}. Find the interquartile range.`, f.q3 - f.q1, `${f.q3} − ${f.q1} = ${f.q3 - f.q1}.`); },
    r => { const f = five(r); return B(`A box-and-whisker plot has median ${f.m}. What percentage of the data is below the median?`, 50, 'Half of the data lies below the median.'); },
    r => { const n = r.pick([40, 60, 80, 100, 120]); return B(`A box plot shows data for ${n} values. How many values lie between $Q_1$ and $Q_3$?`, n / 2, `Half of ${n} = ${n / 2}.`); },
    r => { const n = r.pick([40, 60, 80, 100, 120]); return B(`A box plot shows data for ${n} values. How many values are above $Q_3$?`, n / 4, `A quarter of ${n} = ${n / 4}.`); },
    r => { const f = five(r); return B(`A box plot has $Q_1 = ${f.q1}$ and $Q_3 = ${f.q3}$. A value is an outlier if it is greater than $Q_3 + 1.5 \\times IQR$. Find this upper limit.`, f.q3 + 1.5 * (f.q3 - f.q1), `IQR = ${f.q3 - f.q1}. Limit = ${f.q3} + 1.5 × ${f.q3 - f.q1} = ${f.q3 + 1.5 * (f.q3 - f.q1)}.`); },
    r => { const f = five(r); return B(`A box plot has $Q_1 = ${f.q1}$ and $Q_3 = ${f.q3}$. A value is an outlier if it is less than $Q_1 - 1.5 \\times IQR$. Find this lower limit.`, f.q1 - 1.5 * (f.q3 - f.q1), `IQR = ${f.q3 - f.q1}. Limit = ${f.q1} − 1.5 × ${f.q3 - f.q1} = ${f.q1 - 1.5 * (f.q3 - f.q1)}.`); },
    r => { const f = five(r); return B(`A box plot has minimum ${f.lo}, $Q_1 = ${f.q1}$, median ${f.m}, $Q_3 = ${f.q3}$ and maximum ${f.hi}. What is the length of the left whisker (from the minimum to $Q_1$)?`, f.q1 - f.lo, `${f.q1} − ${f.lo} = ${f.q1 - f.lo}.`); },
    r => { const f = five(r); return B(`A box plot has minimum ${f.lo}, $Q_1 = ${f.q1}$, median ${f.m}, $Q_3 = ${f.q3}$ and maximum ${f.hi}. What is the length of the right whisker (from $Q_3$ to the maximum)?`, f.hi - f.q3, `${f.hi} − ${f.q3} = ${f.hi - f.q3}.`); },
    r => { const f = five(r); return B(`A box plot has $Q_1 = ${f.q1}$, median ${f.m}, $Q_3 = ${f.q3}$. Find the length of the box.`, f.q3 - f.q1, `${f.q3} − ${f.q1} = ${f.q3 - f.q1}.`); },
    r => { const f = five(r), g2 = five(r); return B(`Class A has a median of ${f.m + 10} and Class B has a median of ${g2.m + 3}. Find the difference between the two medians.`, Math.abs(f.m - g2.m + 7), `|${f.m + 10} − ${g2.m + 3}| = ${Math.abs(f.m - g2.m + 7)}.`); },
    r => { const f = five(r), k = r.int(2, 5); return B(`Every value in a data set is increased by ${k}. The median was ${f.m}. Find the new median.`, f.m + k, `The median increases by ${k}: ${f.m + k}.`); },
    r => { const f = five(r), k = r.int(2, 4); return B(`Every value in a data set is multiplied by ${k}. The interquartile range was ${f.q3 - f.q1}. Find the new interquartile range.`, (f.q3 - f.q1) * k, `The IQR is multiplied by ${k}: ${(f.q3 - f.q1) * k}.`); },
    r => { const d = dl(r, 9, 10, 60), q = quart(d), s = sorted(d); return B(`The data ${d.join(', ')} is shown on a box plot. Find the median.`, q.q2, `In order: ${s.join(', ')}. The median is ${q.q2}.`); },
    r => { const f = five(r); return B(`The five-number summary of a data set is ${f.lo}, ${f.q1}, ${f.m}, ${f.q3}, ${f.hi}. Find the sum of the median and the lower quartile.`, f.m + f.q1, `${f.m} + ${f.q1} = ${f.m + f.q1}.`); },
    r => { const n = r.pick([20, 40, 60, 80]), p = r.pick([25, 50, 75]); return B(`A box plot is drawn for ${n} values. How many values are at or below the ${p === 25 ? 'lower quartile' : p === 50 ? 'median' : 'upper quartile'}?`, n * p / 100, `${p}% of ${n} = ${n * p / 100}.`); }
  ], word: [
    r => { const f = five(r); return B(`The box plot of the times (in minutes) taken by students to complete a task shows minimum ${f.lo}, $Q_1 = ${f.q1}$, median ${f.m}, $Q_3 = ${f.q3}$ and maximum ${f.hi}. Find the interquartile range.`, f.q3 - f.q1, `${f.q3} − ${f.q1} = ${f.q3 - f.q1} minutes.`); },
    r => { const f = five(r), n = r.pick([40, 80, 120, 200]); return B(`A box plot shows the marks of ${n} students. How many students scored more than the upper quartile mark?`, n / 4, `A quarter of ${n} = ${n / 4}.`); },
    r => { const a = five(r), b = five(r); if (a.q3 - a.q1 === b.q3 - b.q1) return null; return B(`Two classes' marks are shown on box plots. Class A has IQR ${a.q3 - a.q1} and Class B has IQR ${b.q3 - b.q1}. Find the difference between the IQRs (larger minus smaller).`, Math.abs((a.q3 - a.q1) - (b.q3 - b.q1)), `The difference is ${Math.abs((a.q3 - a.q1) - (b.q3 - b.q1))}.`); },
    r => { const f = five(r); return B(`The box plot of the daily rainfall (mm) in a month has median ${f.m} and range ${f.hi - f.lo}. If the minimum is ${f.lo}, find the maximum.`, f.hi, `Maximum = ${f.lo} + ${f.hi - f.lo} = ${f.hi}.`); },
    r => { const f = five(r); return B(`The weights (kg) of parcels have $Q_1 = ${f.q1}$ and $Q_3 = ${f.q3}$. A parcel is an outlier if its weight is more than $Q_3 + 1.5 \\times IQR$. Find the smallest whole-number weight that is an outlier.`, Math.floor(f.q3 + 1.5 * (f.q3 - f.q1)) + 1, `Limit = ${f.q3 + 1.5 * (f.q3 - f.q1)}. The smallest whole number above it is ${Math.floor(f.q3 + 1.5 * (f.q3 - f.q1)) + 1}.`); },
    r => { const f = five(r), n = r.pick([40, 60, 80, 100]); return B(`A box plot of ${n} test scores has median ${f.m}. How many students scored below the median?`, n / 2, `Half of ${n} = ${n / 2}.`); }
  ]});

  /* ---- Standard deviation ---- */
  const sdSet = (r) => { const m = r.int(8, 20), d = [r.int(-4, -1), r.int(-3, 3), r.int(1, 4), r.int(-2, 2)]; d.push(-sum(d)); return d.map(v => m + v); };
  g.push({id: 'G3.4.data-analysis-measures-of-spread.4', plain: [
    r => { const d = sdSet(r); return B(`Find the standard deviation of ${d.join(', ')} correct to 2 decimal places.`, rd(sd(d), 2), `Mean = ${sum(d) / 5}. Standard deviation = ${rd(sd(d), 2)}.`); },
    r => { const d = sdSet(r); return B(`Find the mean of ${d.join(', ')}.`, sum(d) / 5, `${sum(d)} ÷ 5 = ${sum(d) / 5}.`); },
    r => { const n = r.int(5, 10), m = r.int(8, 20), v = r.int(2, 6); return B(`For ${n} values, $\\sum x = ${n * m}$ and $\\sum x^2 = ${n * (m * m + v * v)}$. Find the standard deviation.`, v, `$\\sigma = \\sqrt{\\dfrac{${n * (m * m + v * v)}}{${n}} - ${m}^2} = \\sqrt{${v * v}} = ${v}$.`); },
    r => { const d = sdSet(r), k = r.int(2, 9); return B(`The standard deviation of a data set is ${rd(sd(d), 2)}. Each value is increased by ${k}. Find the new standard deviation.`, rd(sd(d), 2), 'Adding a constant does not change the standard deviation.'); },
    r => { const d = sdSet(r), k = r.pick([2, 3, 4]); return B(`The standard deviation of a data set is ${rd(sd(d), 2)}. Each value is multiplied by ${k}. Find the new standard deviation correct to 2 decimal places.`, rd(sd(d) * k, 2), `The standard deviation is multiplied by ${k}: ${rd(sd(d) * k, 2)}.`); },
    r => { const a = r.int(2, 4), b = a + r.int(1, 3); return B(`Set A has standard deviation ${a} and Set B has standard deviation ${b}. Which set is more spread out? Type 1 for A or 2 for B.`, 2, 'A larger standard deviation means more spread.'); },
    r => { const d = [r.int(3, 7), r.int(3, 7), r.int(3, 7)]; const m = sum(d) / 3; return B(`Find the standard deviation of ${d.join(', ')} correct to 2 decimal places.`, rd(sd(d), 2), `Mean = ${rd(m, 2)}. $\\sigma = ${rd(sd(d), 2)}$.`); },
    r => { const m = r.int(10, 40), n = r.int(4, 12); return B(`The mean of ${n} values is ${m}. All values are equal. Find the standard deviation.`, 0, 'If all values are equal, none deviates from the mean, so $\\sigma = 0$.'); },
    r => { const d = sdSet(r); return B(`Find the variance of ${d.join(', ')} correct to 2 decimal places.`, rd(sd(d) ** 2, 2), `Variance = $\\sigma^2 = ${rd(sd(d) ** 2, 2)}$.`); },
    r => { const a = [r.int(10, 20), r.int(10, 20)], m = sum(a) / 2; return B(`Find the standard deviation of ${a.join(' and ')} correct to 2 decimal places.`, rd(sd(a), 2), `Mean = ${m}. Each value is ${Math.abs(a[0] - m)} from the mean, so $\\sigma = ${rd(sd(a), 2)}$.`); },
    r => { const n = r.int(6, 12), m = r.int(10, 30), v = r.int(2, 8); return B(`For ${n} values, $\\sum x^2 = ${n * (m * m + v * v)}$ and the mean is ${m}. Find the variance.`, v * v, `Variance = $\\dfrac{\\sum x^2}{n} - \\text{mean}^2 = ${m * m + v * v} - ${m * m} = ${v * v}$.`); },
    r => { const d = sdSet(r); return B(`Find $\\sum (x - \\bar{x})^2$ for ${d.join(', ')}.`, rd(sd(d) ** 2 * 5, 2), `The mean is ${sum(d) / 5}. The sum of squared deviations is ${rd(sd(d) ** 2 * 5, 2)}.`); },
    r => { const s = r.int(2, 6), k = r.int(2, 5); return B(`The standard deviation of a set is ${s}. After subtracting ${k} from every value, what is the new standard deviation?`, s, 'Subtracting a constant does not change the spread.'); },
    r => { const a = r.int(4, 9), b = r.int(10, 16); return B(`Find the standard deviation of ${a}, ${b} correct to 2 decimal places.`, rd(sd([a, b]), 2), `$\\sigma = \\dfrac{|${b} - ${a}|}{2} = ${rd(sd([a, b]), 2)}$.`); },
    r => { const d = sdSet(r); const e = d.map(x => x + 1); return B(`Data set $P$ is ${d.join(', ')}. Data set $Q$ is obtained by adding 1 to every value. Find the standard deviation of $Q$ correct to 2 decimal places.`, rd(sd(e), 2), `The standard deviation is unchanged: ${rd(sd(d), 2)}.`); }
  ], word: [
    r => { const d = sdSet(r); return B(`A basketball player scored ${d.join(', ')} points in five games. Find the standard deviation of the scores, correct to 2 decimal places.`, rd(sd(d), 2), `Mean = ${sum(d) / 5}. $\\sigma = ${rd(sd(d), 2)}$.`); },
    r => { const d = sdSet(r); return B(`The heights (cm) of five plants are ${d.map(x => x + 20).join(', ')}. Find the standard deviation of their heights, correct to 2 decimal places.`, rd(sd(d), 2), `Subtracting 20 from each value does not change the standard deviation: ${rd(sd(d), 2)}.`); },
    r => { const a = r.int(2, 4), b = a + r.int(1, 3); return B(`Machine A fills bottles with a standard deviation of ${a} ml and Machine B with a standard deviation of ${b} ml. Which machine is more consistent? Type 1 for A or 2 for B.`, 1, 'The smaller standard deviation means more consistent.'); },
    r => { const s = r.int(2, 5), k = r.pick([2, 3, 10]); return B(`The times of a class of runners have a standard deviation of ${s} seconds. All times are multiplied by ${k} when converted to a new unit. Find the new standard deviation.`, s * k, `${s} × ${k} = ${s * k}.`); },
    r => { const d = [r.int(60, 70), r.int(70, 80), r.int(80, 90)]; return B(`Three students scored ${d.join(', ')} in a test. Find the standard deviation of their scores correct to 2 decimal places.`, rd(sd(d), 2), `Mean = ${rd(sum(d) / 3, 2)}. $\\sigma = ${rd(sd(d), 2)}$.`); },
    r => { const n = r.int(8, 15), m = r.int(20, 50), v = r.int(2, 8); return B(`A shop records the daily sales of ${n} days. The mean is \\$${m} and $\\sum x^2 = ${n * (m * m + v * v)}$. Find the standard deviation in dollars.`, v, `$\\sigma = \\sqrt{${m * m + v * v} - ${m * m}} = ${v}$.`); }
  ]});

  /* ---- Probability of combined events ---- */
  g.push({id: 'G3.4.probability.1', plain: [
    r => { const p = r.pick([0.1, 0.2, 0.25, 0.4, 0.5]), q = r.pick([0.2, 0.4, 0.5, 0.6]); return B(`$A$ and $B$ are independent events with $P(A) = ${p}$ and $P(B) = ${q}$. Find $P(A \\text{ and } B)$.`, rd(p * q, 4), `$P(A \\cap B) = ${p} \\times ${q} = ${rd(p * q, 4)}$.`); },
    r => { const p = r.pick([0.1, 0.2, 0.25, 0.3]), q = r.pick([0.2, 0.4, 0.5]); return B(`$A$ and $B$ are mutually exclusive with $P(A) = ${p}$ and $P(B) = ${q}$. Find $P(A \\text{ or } B)$.`, rd(p + q, 4), `$P(A \\cup B) = ${p} + ${q} = ${rd(p + q, 4)}$.`); },
    r => { const p = r.pick([0.4, 0.5, 0.6]), q = r.pick([0.3, 0.4, 0.5]), c = r.pick([0.1, 0.2]); return B(`$P(A) = ${p}$, $P(B) = ${q}$ and $P(A \\cap B) = ${c}$. Find $P(A \\cup B)$.`, rd(p + q - c, 4), `$P(A \\cup B) = ${p} + ${q} - ${c} = ${rd(p + q - c, 4)}$.`); },
    r => { const a = r.pick([2, 3, 4, 5]), t = r.pick([10, 20]); return B(`A bag has ${t} balls, ${a} of them red. A ball is drawn, replaced and a second ball is drawn. Find the probability that both are red, as a decimal.`, rd((a / t) ** 2, 4), `$\\left(\\dfrac{${a}}{${t}}\\right)^2 = ${rd((a / t) ** 2, 4)}$.`); },
    r => { const a = r.int(3, 6), t = r.int(a + 3, a + 8); return B(`A bag has ${t} balls, ${a} of them red. Two balls are drawn without replacement. Find the probability that both are red, as a percentage correct to 1 decimal place.`, rd(a / t * (a - 1) / (t - 1) * 100, 1), `$\\dfrac{${a}}{${t}} \\times \\dfrac{${a - 1}}{${t - 1}} = ${rd(a / t * (a - 1) / (t - 1), 4)}$, which is ${rd(a / t * (a - 1) / (t - 1) * 100, 1)}%.`); },
    r => { const p = r.pick([0.1, 0.2, 0.25, 0.4, 0.5]); return B(`The probability that a basketball player scores a free throw is ${p}. Find the probability that she misses both of two independent throws.`, rd((1 - p) ** 2, 4), `$(1 - ${p})^2 = ${rd((1 - p) ** 2, 4)}$.`); },
    r => { const p = r.pick([0.1, 0.2, 0.25, 0.4, 0.5]); return B(`The probability that a basketball player scores a free throw is ${p}. Find the probability that she scores at least once in two independent throws.`, rd(1 - (1 - p) ** 2, 4), `$1 - (1 - ${p})^2 = ${rd(1 - (1 - p) ** 2, 4)}$.`); },
    r => { const k = r.int(2, 12); const ways = k <= 7 ? k - 1 : 13 - k; return B(`Two fair dice are thrown. How many of the 36 outcomes give a total of ${k}?`, ways, `The pairs with sum ${k}: ${ways} outcomes.`); },
    r => { const n = r.int(2, 4); return B(`A fair coin is tossed ${n} times. How many outcomes have exactly 1 head?`, n, `The head can come on any of the ${n} tosses: ${n} outcomes.`); },
    r => { const p = r.pick([0.2, 0.25, 0.4, 0.5]), q = r.pick([0.2, 0.4, 0.5, 0.6]); return B(`Events $A$ and $B$ are independent with $P(A) = ${p}$ and $P(B) = ${q}$. Find the probability that neither $A$ nor $B$ occurs.`, rd((1 - p) * (1 - q), 4), `$(1 - ${p})(1 - ${q}) = ${rd((1 - p) * (1 - q), 4)}$.`); },
    r => { const a = r.int(3, 6), b = r.int(3, 6), t = 20; if (a + b >= t) return null; return B(`A bag has ${a} red, ${b} blue and ${t - a - b} green balls. One ball is drawn. Find the probability that it is red or blue, as a decimal.`, rd((a + b) / t, 4), `$\\dfrac{${a} + ${b}}{${t}} = ${rd((a + b) / t, 4)}$.`); },
    r => { const n = r.pick([2, 3]); return B(`A tree diagram has ${n} stages and each stage has 2 branches. How many outcomes are there at the end?`, 2 ** n, `$2^{${n}} = ${2 ** n}$.`); },
    r => { const p = r.pick([0.2, 0.4, 0.5]), n = r.pick([50, 100, 200]); return B(`The probability that a ticket wins is ${p}. If ${n} independent tickets are bought, how many winning tickets are expected?`, n * p, `${n} × ${p} = ${n * p}.`); },
    r => { const p = r.pick([0.3, 0.4, 0.6]), q = r.pick([0.2, 0.5]); return B(`$P(A) = ${p}$ and $P(B') = ${q}$. Find $P(B)$.`, rd(1 - q, 4), `$P(B) = 1 - ${q} = ${rd(1 - q, 4)}$.`); },
    r => { const a = r.int(2, 5), b = r.int(2, 5), t = r.int(a + b + 2, a + b + 7); return B(`A box has ${t} cards. ${a} are red and ${b} are blue. Two cards are drawn with replacement. Find the probability that the first is red and the second is blue, as a percentage correct to 1 decimal place.`, rd(a / t * b / t * 100, 1), `$\\dfrac{${a}}{${t}} \\times \\dfrac{${b}}{${t}} = ${rd(a * b / (t * t), 4)}$, which is ${rd(a / t * b / t * 100, 1)}%.`); }
  ], word: [
    r => { const p = r.pick([0.2, 0.3, 0.4, 0.5]); return B(`The probability that it rains on Saturday is ${p} and on Sunday is ${p}, independently. Find the probability that it rains on both days.`, rd(p * p, 4), `${p} × ${p} = ${rd(p * p, 4)}.`); },
    r => { const p = r.pick([0.1, 0.2, 0.25]), q = r.pick([0.2, 0.3, 0.4]); return B(`Machine A produces a faulty item with probability ${p} and machine B with probability ${q}, independently. Find the probability that both produce a faulty item.`, rd(p * q, 4), `${p} × ${q} = ${rd(p * q, 4)}.`); },
    r => { const a = r.int(3, 6), t = r.int(a + 4, a + 8); return B(`A box has ${t} chocolates and ${a} of them are mint. Two chocolates are taken at random without replacement. Find the probability that both are mint, as a percentage correct to 1 decimal place.`, rd(a / t * (a - 1) / (t - 1) * 100, 1), `$\\dfrac{${a}}{${t}} \\times \\dfrac{${a - 1}}{${t - 1}} = ${rd(a / t * (a - 1) / (t - 1), 4)}$, which is ${rd(a / t * (a - 1) / (t - 1) * 100, 1)}%.`); },
    r => { const p = r.pick([0.4, 0.5, 0.6]), n = 3; return B(`A student passes each of 3 independent quizzes with probability ${p}. Find the probability that the student fails all 3.`, rd((1 - p) ** 3, 4), `$(1 - ${p})^3 = ${rd((1 - p) ** 3, 4)}$.`); },
    r => { const p = r.pick([0.2, 0.25, 0.4, 0.5]); return B(`A traffic light is red with probability ${p} each time a driver arrives, independently each day. Find the probability that the light is red on both of two days.`, rd(p * p, 4), `${p} × ${p} = ${rd(p * p, 4)}.`); },
    r => { const a = r.int(2, 5), b = r.int(2, 5), t = a + b + r.int(3, 8); return B(`A bag has ${t} sweets: ${a} are orange and ${b} are lemon. Two sweets are picked with replacement. Find the probability that both are orange, as a percentage correct to 1 decimal place.`, rd((a / t) ** 2 * 100, 1), `$\\left(\\dfrac{${a}}{${t}}\\right)^2 = ${rd((a / t) ** 2, 4)}$, which is ${rd((a / t) ** 2 * 100, 1)}%.`); }
  ]});

  /* ---- Matrices ---- */
  const M = (a, b, c, d) => `\\begin{pmatrix} ${a} & ${b} \\\\ ${c} & ${d} \\end{pmatrix}`;
  const m2 = r => [r.int(1, 6), r.int(0, 6), r.int(0, 6), r.int(1, 6)];
  g.push({id: 'G3.4.matrices.1', plain: [
    r => { const r1 = r.int(2, 4), c1 = r.int(2, 4), c2 = r.int(2, 4); return B(`Matrix $A$ has order ${r1} × ${c1} and matrix $B$ has order ${c1} × ${c2}. Find the number of columns in the product $AB$.`, c2, `The product has order ${r1} × ${c2}, so it has ${c2} columns.`); },
    r => { const r1 = r.int(2, 4), c1 = r.int(2, 4), c2 = r.int(2, 4); return B(`Matrix $A$ has order ${r1} × ${c1} and matrix $B$ has order ${c1} × ${c2}. Find the number of rows in the product $AB$.`, r1, `The product has order ${r1} × ${c2}, so it has ${r1} rows.`); },
    r => { const a = m2(r), b = m2(r); return B(`$A = ${M(...a)}$ and $B = ${M(...b)}$. Find the entry in the first row and first column of $A + B$.`, a[0] + b[0], `${a[0]} + ${b[0]} = ${a[0] + b[0]}.`); },
    r => { const a = m2(r), b = m2(r); return B(`$A = ${M(...a)}$ and $B = ${M(...b)}$. Find the entry in the second row and second column of $A - B$.`, a[3] - b[3], `${a[3]} − ${b[3]} = ${a[3] - b[3]}.`); },
    r => { const a = m2(r), k = r.int(2, 5); return B(`$A = ${M(...a)}$. Find the entry in the first row and second column of $${k}A$.`, k * a[1], `${k} × ${a[1]} = ${k * a[1]}.`); },
    r => { const a = m2(r), b = m2(r); return B(`$A = ${M(...a)}$ and $B = ${M(...b)}$. Find the entry in the first row and first column of $AB$.`, a[0] * b[0] + a[1] * b[2], `${a[0]} × ${b[0]} + ${a[1]} × ${b[2]} = ${a[0] * b[0] + a[1] * b[2]}.`); },
    r => { const a = m2(r), b = m2(r); return B(`$A = ${M(...a)}$ and $B = ${M(...b)}$. Find the entry in the second row and second column of $AB$.`, a[2] * b[1] + a[3] * b[3], `${a[2]} × ${b[1]} + ${a[3]} × ${b[3]} = ${a[2] * b[1] + a[3] * b[3]}.`); },
    r => { const x = r.int(1, 9), y = r.int(1, 9); return B(`$\\begin{pmatrix} x & 3 \\\\ 2 & y \\end{pmatrix} + \\begin{pmatrix} 2 & 1 \\\\ 4 & 5 \\end{pmatrix} = \\begin{pmatrix} ${x + 2} & 4 \\\\ 6 & ${y + 5} \\end{pmatrix}$. Find $x + y$.`, x + y, `$x + 2 = ${x + 2}$ gives $x = ${x}$ and $y + 5 = ${y + 5}$ gives $y = ${y}$. So $x + y = ${x + y}$.`); },
    r => { const a = m2(r); return B(`$A = ${M(...a)}$. Find the sum of all the entries of $2A$.`, 2 * (a[0] + a[1] + a[2] + a[3]), `Sum of entries of $A$ = ${a[0] + a[1] + a[2] + a[3]}; doubled = ${2 * (a[0] + a[1] + a[2] + a[3])}.`); },
    r => { const a = r.int(1, 5), b = r.int(1, 5), c = r.int(1, 5), d = r.int(1, 5); return B(`Find the product $\\begin{pmatrix} ${a} & ${b} \\end{pmatrix}\\begin{pmatrix} ${c} \\\\ ${d} \\end{pmatrix}$.`, a * c + b * d, `${a} × ${c} + ${b} × ${d} = ${a * c + b * d}.`); },
    r => { const k = r.int(2, 5), x = r.int(1, 8); return B(`$${k}\\begin{pmatrix} x & 2 \\end{pmatrix} = \\begin{pmatrix} ${k * x} & ${2 * k} \\end{pmatrix}$. Find $x$.`, x, `${k}x = ${k * x}, so $x = ${x}$.`); },
    r => { const r1 = r.int(2, 5), c1 = r.int(2, 5); return B(`How many entries are there in a matrix of order ${r1} × ${c1}?`, r1 * c1, `${r1} × ${c1} = ${r1 * c1}.`); },
    r => { const a = m2(r), b = m2(r); return B(`$A = ${M(...a)}$ and $B = ${M(...b)}$. Find the entry in the first row and second column of $A + B$.`, a[1] + b[1], `${a[1]} + ${b[1]} = ${a[1] + b[1]}.`); },
    r => { const a = m2(r), b = m2(r); return B(`$A = ${M(...a)}$ and $B = ${M(...b)}$. Find the entry in the second row and first column of $AB$.`, a[2] * b[0] + a[3] * b[2], `${a[2]} × ${b[0]} + ${a[3]} × ${b[2]} = ${a[2] * b[0] + a[3] * b[2]}.`); },
    r => { const a = m2(r), k = r.int(2, 4); return B(`$A = ${M(...a)}$. Find the entry in the second row and first column of $${k}A$.`, k * a[2], `${k} × ${a[2]} = ${k * a[2]}.`); }
  ], word: [
    r => { const p = r.int(2, 5), b = r.int(5, 12), n = r.int(3, 8), m = r.int(2, 6); return B(`A shop sells pens at \\$${p} each and books at \\$${b} each. Aisha buys ${n} pens and ${m} books. Using the matrix product $\\begin{pmatrix} ${n} & ${m} \\end{pmatrix}\\begin{pmatrix} ${p} \\\\ ${b} \\end{pmatrix}$, find the total cost in dollars.`, n * p + m * b, `${n} × ${p} + ${m} × ${b} = ${n * p + m * b}.`); },
    r => { const a = r.int(20, 50), b = r.int(15, 40), c = r.int(10, 30), d = r.int(25, 60); return B(`The matrices $\\begin{pmatrix} ${a} & ${b} \\end{pmatrix}$ and $\\begin{pmatrix} ${c} & ${d} \\end{pmatrix}$ show the number of burgers and fries sold on Monday and Tuesday. Find the total number of burgers sold over the two days.`, a + c, `${a} + ${c} = ${a + c}.`); },
    r => { const a = r.int(5, 12), k = r.int(3, 5); return B(`A school sells ${a} tickets each day. Using scalar multiplication, find the number of tickets sold in ${k} days.`, a * k, `${a} × ${k} = ${a * k}.`); },
    r => { const a = r.int(2, 5), b = r.int(1, 4), p = r.int(3, 9), q = r.int(2, 8); return B(`Matrix $\\begin{pmatrix} ${a} & ${b} \\end{pmatrix}$ shows the number of adult and child tickets Ben buys. Matrix $\\begin{pmatrix} ${p} \\\\ ${q} \\end{pmatrix}$ shows the ticket prices in dollars. Find the total cost in dollars.`, a * p + b * q, `${a} × ${p} + ${b} × ${q} = ${a * p + b * q}.`); },
    r => { const a = r.int(10, 30), b = r.int(10, 30), c = r.int(10, 30), d = r.int(10, 30); return B(`Two shops' weekly sales (in dollars) of two items are given by $\\begin{pmatrix} ${a} & ${b} \\end{pmatrix}$ and $\\begin{pmatrix} ${c} & ${d} \\end{pmatrix}$. Find the total sales of the second item.`, b + d, `${b} + ${d} = ${b + d}.`); },
    r => { const a = r.int(2, 4), b = r.int(2, 4), p = r.int(2, 6), q = r.int(2, 6), r2 = r.int(2, 6), s = r.int(2, 6); return B(`Matrix $\\begin{pmatrix} ${a} & ${b} \\end{pmatrix}$ shows the quantities of two fruits bought. The prices (in dollars) of the fruits at two shops are $\\begin{pmatrix} ${p} & ${r2} \\\\ ${q} & ${s} \\end{pmatrix}$ (each column is a shop). Find the total cost at the first shop in dollars.`, a * p + b * q, `${a} × ${p} + ${b} × ${q} = ${a * p + b * q}.`); }
  ]});

  /* ---- Vectors (5.1-5.3): column vectors, magnitude, addition, scalar multiples ---- */
  const V = (x, y) => `\\begin{pmatrix} ${x} \\\\ ${y} \\end{pmatrix}`;
  const T = [[3, 4, 5], [6, 8, 10], [5, 12, 13]];
  g.push({id: 'G3.4.vectors-in-two-dimensions.1', plain: [
    r => { const t = r.pick(T); return B(`Find the magnitude of the vector $${V(t[0], t[1])}$.`, t[2], `$\\sqrt{${t[0]}^2 + ${t[1]}^2} = ${t[2]}$.`); },
    r => { const a = [r.int(-5, 6), r.int(-5, 6)], b = [r.int(-5, 6), r.int(-5, 6)]; return B(`$\\mathbf{a} = ${V(...a)}$ and $\\mathbf{b} = ${V(...b)}$. Find the $x$-component of $\\mathbf{a} + \\mathbf{b}$.`, a[0] + b[0], `${a[0]} + ${b[0]} = ${a[0] + b[0]}.`); },
    r => { const a = [r.int(-5, 6), r.int(-5, 6)], b = [r.int(-5, 6), r.int(-5, 6)]; return B(`$\\mathbf{a} = ${V(...a)}$ and $\\mathbf{b} = ${V(...b)}$. Find the $y$-component of $\\mathbf{a} - \\mathbf{b}$.`, a[1] - b[1], `${a[1]} − (${b[1]}) = ${a[1] - b[1]}.`); },
    r => { const a = [r.int(-5, 6), r.int(-5, 6)], k = r.int(2, 5); return B(`$\\mathbf{a} = ${V(...a)}$. Find the $x$-component of $${k}\\mathbf{a}$.`, k * a[0], `${k} × ${a[0]} = ${k * a[0]}.`); },
    r => { const A = [r.int(-4, 5), r.int(-4, 5)], d = [r.int(-5, 6), r.int(-5, 6)]; const Bp = [A[0] + d[0], A[1] + d[1]]; return B(`$A$ is the point $(${A[0]}, ${A[1]})$ and $B$ is the point $(${Bp[0]}, ${Bp[1]})$. Find the $x$-component of the vector $\\overrightarrow{AB}$.`, d[0], `${Bp[0]} − (${A[0]}) = ${d[0]}.`); },
    r => { const A = [r.int(-4, 5), r.int(-4, 5)], d = [r.int(-5, 6), r.int(-5, 6)]; const Bp = [A[0] + d[0], A[1] + d[1]]; return B(`$A$ is the point $(${A[0]}, ${A[1]})$ and $B$ is the point $(${Bp[0]}, ${Bp[1]})$. Find the $y$-component of the vector $\\overrightarrow{AB}$.`, d[1], `${Bp[1]} − (${A[1]}) = ${d[1]}.`); },
r => { const x = r.int(-5, 6), y = r.int(-5, 6); return B(`The vectors $${V('x', 'y')}$ and $${V(x, y)}$ are equal. Find $x + y$.`, x + y, `Equal vectors have equal components: $x = ${x}$, $y = ${y}$, so $x + y = ${x + y}$.`); },
    r => { const k = r.int(2, 5), a = [r.int(1, 4), r.int(1, 4)]; return B(`The vector $${V(a[0], a[1])}$ is parallel to $${V('k', a[1] * 3)}$. Find $k$.`, a[0] * 3, `The ratio of components is the same: $\\dfrac{k}{${a[0]}} = \\dfrac{${a[1] * 3}}{${a[1]}} = 3$, so $k = ${a[0] * 3}$.`); },
    r => { const t = r.pick(T), k = r.int(2, 4); return B(`The vector $\\mathbf{p} = ${V(t[0], t[1])}$. Find the magnitude of $${k}\\mathbf{p}$.`, k * t[2], `$|${k}\\mathbf{p}| = ${k} \\times ${t[2]} = ${k * t[2]}$.`); },
    r => { const a = [r.int(-3, 4), r.int(-3, 4)], b = [r.int(-3, 4), r.int(-3, 4)], k = r.int(2, 3); return B(`$\\mathbf{a} = ${V(...a)}$ and $\\mathbf{b} = ${V(...b)}$. Find the $x$-component of $${k}\\mathbf{a} + \\mathbf{b}$.`, k * a[0] + b[0], `${k} × ${a[0]} + ${b[0]} = ${k * a[0] + b[0]}.`); },
    r => { const a = [r.int(-3, 4), r.int(-3, 4)], b = [r.int(-3, 4), r.int(-3, 4)], k = r.int(2, 3); return B(`$\\mathbf{a} = ${V(...a)}$ and $\\mathbf{b} = ${V(...b)}$. Find the $y$-component of $\\mathbf{a} - ${k}\\mathbf{b}$.`, a[1] - k * b[1], `${a[1]} − ${k} × (${b[1]}) = ${a[1] - k * b[1]}.`); },
    r => { const d = [r.int(-4, 5), r.int(-4, 5)], P = [r.int(-3, 4), r.int(-3, 4)]; return B(`A point $P(${P[0]}, ${P[1]})$ is translated by the vector $${V(...d)}$. Find the $x$-coordinate of the image.`, P[0] + d[0], `${P[0]} + (${d[0]}) = ${P[0] + d[0]}.`); },
    r => { const d = [r.int(-4, 5), r.int(-4, 5)], P = [r.int(-3, 4), r.int(-3, 4)]; return B(`A point $P(${P[0]}, ${P[1]})$ is translated by the vector $${V(...d)}$. Find the $y$-coordinate of the image.`, P[1] + d[1], `${P[1]} + (${d[1]}) = ${P[1] + d[1]}.`); },
    r => { const a = r.int(2, 8), b = r.int(2, 8); return B(`Find the magnitude of the vector $${V(a, b)}$ correct to 1 decimal place.`, rd(Math.sqrt(a * a + b * b), 1), `$\\sqrt{${a}^2 + ${b}^2} = ${rd(Math.sqrt(a * a + b * b), 2)}$ ≈ ${rd(Math.sqrt(a * a + b * b), 1)}.`); },
    r => { const a = [r.int(1, 6), r.int(1, 6)]; return B(`$\\mathbf{a} = ${V(...a)}$. Find the $x$-component of $-\\mathbf{a}$.`, -a[0], `$-\\mathbf{a} = ${V(-a[0], -a[1])}$.`); }
  ], word: [
    r => { const t = r.pick(T), k = r.int(1, 3); return B(`A boat's displacement is $${V(t[0] * k, t[1] * k)}$ km (east, north). Find the distance the boat has moved from its start, in km.`, t[2] * k, `$\\sqrt{${t[0] * k}^2 + ${t[1] * k}^2} = ${t[2] * k}$ km.`); },
    r => { const a = [r.int(2, 8), r.int(2, 8)], b = [r.int(2, 8), r.int(2, 8)]; return B(`A hiker walks $${V(...a)}$ km and then $${V(...b)}$ km (east, north). How far east is the hiker from the start, in km?`, a[0] + b[0], `${a[0]} + ${b[0]} = ${a[0] + b[0]} km.`); },
    r => { const a = [r.int(2, 8), r.int(2, 8)], b = [r.int(2, 8), r.int(2, 8)]; return B(`A drone flies $${V(...a)}$ m and then $${V(...b)}$ m (east, north). How far north is it from the start, in metres?`, a[1] + b[1], `${a[1]} + ${b[1]} = ${a[1] + b[1]} m.`); },
    r => { const t = r.pick(T), k = r.int(2, 4); return B(`A ferry's velocity is $${V(t[0], t[1])}$ km/h. Find its speed in km/h.`, t[2], `Speed = $\\sqrt{${t[0]}^2 + ${t[1]}^2} = ${t[2]}$ km/h.`); },
    r => { const a = [r.int(2, 8), r.int(2, 8)], k = r.int(2, 5); return B(`A robot moves by the vector $${V(...a)}$ metres each step. How far east has it moved after ${k} steps, in metres?`, a[0] * k, `${a[0]} × ${k} = ${a[0] * k} m.`); },
    r => { const P = [r.int(1, 5), r.int(1, 5)], Q = [r.int(6, 12), r.int(6, 12)]; return B(`A town $Q$ is at $(${Q[0]}, ${Q[1]})$ and a town $P$ is at $(${P[0]}, ${P[1]})$ on a map (units in km). Find the $x$-component of the vector from $P$ to $Q$ in km.`, Q[0] - P[0], `${Q[0]} − ${P[0]} = ${Q[0] - P[0]}.`); }
  ]});

  /* ---- Vectors (5.4-5.5): position vectors, midpoints and geometry ---- */
  g.push({id: 'G3.4.vectors-in-two-dimensions.2', plain: [
    r => { const a = [r.int(-3, 6), r.int(-3, 6)], b = [r.int(-3, 6), r.int(-3, 6)]; return B(`$\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OB} = ${V(...b)}$. Find the $x$-component of $\\overrightarrow{AB}$.`, b[0] - a[0], `$\\overrightarrow{AB} = \\overrightarrow{OB} - \\overrightarrow{OA}$: ${b[0]} − (${a[0]}) = ${b[0] - a[0]}.`); },
    r => { const a = [r.int(-3, 6), r.int(-3, 6)], b = [r.int(-3, 6), r.int(-3, 6)]; return B(`$\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OB} = ${V(...b)}$. Find the $y$-component of $\\overrightarrow{AB}$.`, b[1] - a[1], `${b[1]} − (${a[1]}) = ${b[1] - a[1]}.`); },
    r => { const a = [r.int(-3, 4) * 2, r.int(-3, 4) * 2], b = [r.int(-3, 4) * 2, r.int(-3, 4) * 2]; return B(`$\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OB} = ${V(...b)}$. $M$ is the midpoint of $AB$. Find the $x$-component of $\\overrightarrow{OM}$.`, (a[0] + b[0]) / 2, `$\\overrightarrow{OM} = \\dfrac{1}{2}(\\overrightarrow{OA} + \\overrightarrow{OB})$: (${a[0]} + ${b[0]}) ÷ 2 = ${(a[0] + b[0]) / 2}.`); },
    r => { const a = [r.int(-3, 4) * 2, r.int(-3, 4) * 2], b = [r.int(-3, 4) * 2, r.int(-3, 4) * 2]; return B(`$\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OB} = ${V(...b)}$. $M$ is the midpoint of $AB$. Find the $y$-component of $\\overrightarrow{OM}$.`, (a[1] + b[1]) / 2, `(${a[1]} + ${b[1]}) ÷ 2 = ${(a[1] + b[1]) / 2}.`); },
    r => { const a = [r.int(1, 6), r.int(1, 6)], b = [r.int(1, 6), r.int(1, 6)]; return B(`$OABC$ is a parallelogram with $\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OC} = ${V(...b)}$. Find the $x$-component of $\\overrightarrow{OB}$.`, a[0] + b[0], `$\\overrightarrow{OB} = \\overrightarrow{OA} + \\overrightarrow{OC}$: ${a[0]} + ${b[0]} = ${a[0] + b[0]}.`); },
    r => { const a = [r.int(1, 6), r.int(1, 6)], b = [r.int(1, 6), r.int(1, 6)]; return B(`$OABC$ is a parallelogram with $\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OC} = ${V(...b)}$. Find the $y$-component of $\\overrightarrow{OB}$.`, a[1] + b[1], `${a[1]} + ${b[1]} = ${a[1] + b[1]}.`); },
    r => { const a = [r.int(-3, 5), r.int(-3, 5)], b = [r.int(-3, 5), r.int(-3, 5)], m = r.int(1, 3), n = r.int(1, 3); const t = m + n; const A = [a[0] * t, a[1] * t], Bp = [b[0] * t, b[1] * t]; return B(`$\\overrightarrow{OA} = ${V(...A)}$ and $\\overrightarrow{OB} = ${V(...Bp)}$. $P$ is on $AB$ with $AP : PB = ${m} : ${n}$. Find the $x$-component of $\\overrightarrow{OP}$.`, A[0] + m * (Bp[0] - A[0]) / t, `$\\overrightarrow{OP} = \\overrightarrow{OA} + \\dfrac{${m}}{${t}}\\overrightarrow{AB}$, so the $x$-component is $${A[0]} + ${m}(${Bp[0] - A[0]})/${t} = ${A[0] + m * (Bp[0] - A[0]) / t}$.`); },
    r => { const k = r.int(2, 4), a = [r.int(1, 4), r.int(1, 4)]; return B(`$\\overrightarrow{AB} = ${V(...a)}$ and $\\overrightarrow{CD} = ${V(k * a[0], k * a[1])}$. $\\overrightarrow{CD} = h\\overrightarrow{AB}$. Find $h$.`, k, `Each component of $\\overrightarrow{CD}$ is ${k} times that of $\\overrightarrow{AB}$, so $h = ${k}$.`); },
    r => { const k = r.int(2, 5), a = r.int(1, 5), b = r.int(1, 5); return B(`$\\overrightarrow{OP} = ${V(a, b)}$ and $\\overrightarrow{OQ} = ${V(k * a, k * b)}$. Find $\\dfrac{|\\overrightarrow{OQ}|}{|\\overrightarrow{OP}|}$.`, k, `$\\overrightarrow{OQ} = ${k}\\overrightarrow{OP}$, so the ratio of magnitudes is ${k}.`); },
    r => { const t = r.pick(T), k = r.int(1, 3); const A = [r.int(0, 3), r.int(0, 3)]; return B(`$A$ is $(${A[0]}, ${A[1]})$ and $B$ is $(${A[0] + t[0] * k}, ${A[1] + t[1] * k})$. Find $|\\overrightarrow{AB}|$.`, t[2] * k, `$\\overrightarrow{AB} = ${V(t[0] * k, t[1] * k)}$, with magnitude ${t[2] * k}.`); },
    r => { const a = [r.int(1, 5), r.int(1, 5)], b = [r.int(1, 5), r.int(1, 5)]; return B(`$\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OB} = ${V(...b)}$. Find the $x$-component of $\\overrightarrow{BA}$.`, a[0] - b[0], `$\\overrightarrow{BA} = \\overrightarrow{OA} - \\overrightarrow{OB}$: ${a[0]} − ${b[0]} = ${a[0] - b[0]}.`); },
    r => { const a = [r.int(1, 5), r.int(1, 5)]; const k = r.int(2, 4); return B(`Points $O$, $A$ and $B$ are collinear with $\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OB} = ${V('k', k * a[1])}$. Find $k$.`, k * a[0], `$\\overrightarrow{OB} = ${k}\\overrightarrow{OA}$, so $k = ${k} \\times ${a[0]} = ${k * a[0]}$.`); },
    r => { const a = [r.int(-3, 4), r.int(-3, 4)], b = [r.int(-3, 4), r.int(-3, 4)]; return B(`$\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OB} = ${V(...b)}$. Find the $x$-component of $2\\overrightarrow{OA} - \\overrightarrow{OB}$.`, 2 * a[0] - b[0], `2 × (${a[0]}) − (${b[0]}) = ${2 * a[0] - b[0]}.`); },
    r => { const a = [r.int(1, 5), r.int(1, 5)], b = [r.int(1, 5), r.int(1, 5)]; return B(`In triangle $OAB$, $\\overrightarrow{OA} = ${V(...a)}$ and $\\overrightarrow{OB} = ${V(...b)}$. $M$ is the midpoint of $OA$. Find the $x$-component of $\\overrightarrow{MB}$ as a decimal.`, b[0] - a[0] / 2, `$\\overrightarrow{MB} = \\overrightarrow{OB} - \\dfrac{1}{2}\\overrightarrow{OA}$: ${b[0]} − ${a[0] / 2} = ${b[0] - a[0] / 2}.`); },
r => { const P = [r.int(0, 4), r.int(0, 4)], d = r.int(2, 6); return B(`Find the length of the vector joining $(${P[0]}, ${P[1]})$ to $(${P[0] + d * 3}, ${P[1] + d * 4})$.`, d * 5, `The vector is $${V(3 * d, 4 * d)}$, so its length is $\\sqrt{${(3 * d) ** 2} + ${(4 * d) ** 2}} = ${5 * d}$.`); }
  ], word: [
    r => { const a = [r.int(2, 8), r.int(2, 8)], b = [r.int(2, 8), r.int(2, 8)]; return B(`A boat sails from $O$ to $A$ with displacement $${V(...a)}$ km and then from $A$ to $B$ with displacement $${V(...b)}$ km. Find the $x$-component of $\\overrightarrow{OB}$ in km.`, a[0] + b[0], `${a[0]} + ${b[0]} = ${a[0] + b[0]} km.`); },
    r => { const a = [r.int(2, 6) * 2, r.int(2, 6) * 2], b = [r.int(2, 6) * 2, r.int(2, 6) * 2]; return B(`Two friends live at $A$ and $B$ with position vectors $${V(...a)}$ km and $${V(...b)}$ km from the town centre $O$. They meet at the midpoint of $AB$. Find the $x$-component of the meeting point's position vector in km.`, (a[0] + b[0]) / 2, `(${a[0]} + ${b[0]}) ÷ 2 = ${(a[0] + b[0]) / 2} km.`); },
    r => { const t = r.pick(T), k = r.int(1, 3); return B(`A drone flies from $O$ to $A$ with displacement $${V(t[0] * k, t[1] * k)}$ metres. Find the distance $OA$ in metres.`, t[2] * k, `$\\sqrt{${t[0] * k}^2 + ${t[1] * k}^2} = ${t[2] * k}$ m.`); },
    r => { const a = [r.int(3, 9), r.int(3, 9)], b = [r.int(1, 3), r.int(1, 3)]; return B(`A boat starts at $O$ and its position after 1 hour is $${V(...a)}$ km. A current of $${V(...b)}$ km pushes it for another hour. Find the $y$-component of its final position in km.`, a[1] + b[1], `${a[1]} + ${b[1]} = ${a[1] + b[1]} km.`); },
    r => { const a = [r.int(1, 5), r.int(1, 5)], k = r.int(2, 5); return B(`A robot moves by $${V(...a)}$ metres in one step. After ${k} steps its displacement is $k$ times this. Find the $y$-component of the displacement after ${k} steps, in metres.`, k * a[1], `${k} × ${a[1]} = ${k * a[1]}.`); },
    r => { const A = [r.int(1, 4), r.int(1, 4)], d = [r.int(2, 5), r.int(2, 5)]; return B(`A rescue team at $A(${A[0]}, ${A[1]})$ (units in km) walks to $B$ with displacement $${V(...d)}$ km. Find the $x$-coordinate of $B$.`, A[0] + d[0], `${A[0]} + ${d[0]} = ${A[0] + d[0]}.`); }
  ]});

  return g;
};
